class ModelFormMetaclassTests(TestCase):
    def test_modelformmetaclass_formfield_callback_inheritance(self):
        """
        Test that formfield_callback is properly inherited from base classes.
        """
        # Define a custom formfield callback
        def custom_callback(field, **kwargs):
            return field.formfield(**kwargs)

        # Path 1 & 2: Test with base classes that have formfield_callback
        class BaseFormWithCallback(forms.ModelForm):
            class Meta:
                model = Category
                fields = '__all__'
                formfield_callback = staticmethod(custom_callback)

        class TestForm1(BaseFormWithCallback):
            pass

        # This should not raise any exception and should inherit the callback
        self.assertEqual(TestForm1._meta.formfield_callback, custom_callback)

    def test_modelformmetaclass_no_bases(self):
        """
        Test ModelFormMetaclass with no base classes having formfield_callback.
        """
        # Path 3, 4, 5: Test with no formfield_callback in bases
        class TestModelForm(forms.ModelForm):
            class Meta:
                model = Category
                fields = '__all__'

        # Should work normally without any inherited callback
        self.assertIsNone(TestModelForm._meta.formfield_callback)

    def test_modelformmetaclass_multiple_inheritance(self):
        """
        Test ModelFormMetaclass with multiple inheritance where one base has formfield_callback.
        """
        def callback1(field, **kwargs):
            return field.formfield(**kwargs)

        class BaseForm1(forms.ModelForm):
            class Meta:
                formfield_callback = staticmethod(callback1)

        class BaseForm2(forms.ModelForm):
            pass

        # Path 2: Test with multiple bases where second one has callback
        class TestForm2(BaseForm2, BaseForm1):
            class Meta(BaseForm2.Meta, BaseForm1.Meta):
                model = Category
                fields = '__all__'

        # Should inherit callback from BaseForm1
        self.assertEqual(TestForm2._meta.formfield_callback, callback1)
