class BaseModelFormTests(TestCase):
    def test_init_no_model_class(self):
        class FormWithoutModel(BaseModelForm):
            pass

        with self.assertRaisesMessage(ValueError, 'ModelForm has no model class specified.'):
            FormWithoutModel()

    def test_init_no_instance(self):
        class TestForm(BaseModelForm):
            class Meta:
                model = Category
                fields = '__all__'

        # Test with no instance and no initial data
        form = TestForm()
        self.assertIsInstance(form.instance, Category)
        self.assertEqual(form.initial, {})

        # Test with no instance but with initial data
        initial_data = {'name': 'Initial Category'}
        form = TestForm(initial=initial_data)
        self.assertIsInstance(form.instance, Category)
        self.assertEqual(form.initial, initial_data)

    def test_init_with_instance(self):
        class TestForm(BaseModelForm):
            class Meta:
                model = Category
                fields = '__all__'

        category = Category.objects.create(name='Test Category', slug='test-category', url='test')

        # Test with instance and no initial data
        form = TestForm(instance=category)
        self.assertEqual(form.instance, category)
        expected_initial = {'name': 'Test Category', 'slug': 'test-category', 'url': 'test'}
        self.assertEqual(form.initial, expected_initial)

        # Test with instance and initial data (initial should override instance)
        initial_data = {'name': 'Overridden Name'}
        form = TestForm(instance=category, initial=initial_data)
        self.assertEqual(form.instance, category)
        expected_initial = {'name': 'Overridden Name', 'slug': 'test-category', 'url': 'test'}
        self.assertEqual(form.initial, expected_initial)
