def test_hasnew():
    """Test the hasnew function for both execution paths."""

    # Path 1: obj has __new__ attribute and it's not object.__new__
    class CustomNew:
        def __new__(cls):
            return super().__new__(cls)

    assert hasnew(CustomNew) is True

    # Path 2: obj does not have __new__ attribute
    class NoNew:
        pass

    assert hasnew(NoNew) is False

    # Path 2: obj has __new__ attribute but it's object.__new__
    class JustObjectNew:
        __new__ = object.__new__

    assert hasnew(JustObjectNew) is False
