            __module__ = 'check_framework'
            __classcell__ = 'test_cell'

            class Meta:
                abstract = True

        # Verify the model was created successfully
        self.assertTrue(hasattr(TestModel, '_meta'))

    def test_contributable_vs_non_contributable_attrs(self):
        """Test Path 3: Mix of contributable and non-contributable attributes."""
        def dummy_contribute_method(self, cls, name):
            pass

        class TestField:
            def contribute_to_class(self, cls, name):
                cls.test_field_attr = f"field_{name}"

        field_instance = TestField()

        class TestModel(models.Model):
            __module__ = 'check_framework'
            test_field = field_instance
            regular_attr = 'regular_value'

            class Meta:
                abstract = True

        # Should have processed both contributable and non-contributable attrs
        self.assertTrue(hasattr(TestModel, 'test_field_attr'))
        self.assertEqual(TestModel.regular_attr, 'regular_value')

    def test_missing_app_label_error(self):
        """Test Path 4: Concrete model without app_label and no app config should raise error."""
        with self.assertRaises(RuntimeError) as cm:
            class TestModel(models.Model):
                __module__ = 'nonexistent_app'

                class Meta:
                    abstract = False

        self.assertIn("doesn't declare an explicit app_label", str(cm.exception))

    def test_abstract_model_with_inheritance(self):
        """Test Path 5: Abstract model with base meta inheritance."""
        class BaseModel(models.Model):
            class Meta:
                abstract = True
                ordering = ['name']
                get_latest_by = 'created'

        class ChildModel(BaseModel):
            name = models.CharField(max_length=100)
            created = models.DateTimeField()

            class Meta:
                app_label = 'check_framework'

        # Should inherit ordering and get_latest_by from parent
        self.assertEqual(ChildModel._meta.ordering, ['name'])
        self.assertEqual(ChildModel._meta.get_latest_by, 'created')

    def test_proxy_model_swapped_error(self):
        """Test Path 5: Proxy model with swapped base should raise TypeError."""
        with self.assertRaises(TypeError) as cm:
            class SwappedModel(models.Model):
                class Meta:
                    app_label = 'check_framework'
                    swapped = 'some_app.SomeModel'

            class ProxyModel(SwappedModel):
                class Meta:
                    app_label = 'check_framework'
                    proxy = True

        self.assertIn("cannot proxy the swapped model", str(cm.exception))

    def test_contributable_attrs_processing(self):
        """Test Path 6: Processing of contributable attributes."""
        class TestManager(models.Manager):
            def contribute_to_class(self, cls, name):
                cls.custom_manager = self

        class TestModel(models.Model):
            __module__ = 'check_framework'
            objects = TestManager()

            class Meta:
                app_label = 'check_framework'
                abstract = True

        # The manager should have been processed via contribute_to_class
        self.assertIsInstance(TestModel.custom_manager, TestManager)

    def test_proxy_model_abstract_field_error(self):
        """Test Path 7: Proxy model with abstract parent containing fields should raise error."""
        with self.assertRaises(TypeError) as cm:
            class AbstractWithFields(models.Model):
                name = models.CharField(max_length=100)

                class Meta:
                    abstract = True

            class ProxyModel(AbstractWithFields):
                class Meta:
                    app_label = 'check_framework'
                    proxy = True

        self.assertIn("Abstract base class containing model fields not permitted", str(cm.exception))

    def test_proxy_model_multiple_bases_validation(self):
