        class Base1(models.Model):
            class Meta:
                app_label = 'check_framework'
                abstract = True

        class Base2(models.Model):
            class Meta:
                app_label = 'check_framework'
                abstract = True

        # This should work - no fields in abstract bases
        class ProxyModel(Base1, Base2):
            class Meta:
                app_label = 'check_framework'
                proxy = True

