    right = {"key2": []}

    with pytest.raises(TypeError):
        merge_family(left, right)

def test_merge_family_empty_right():
    """Test merge_family with empty right dictionary"""
    left = {"key1": [1, 2], "key2": [3, 4]}
    right = {}
    expected = {"key1": [1, 2], "key2": [3, 4]}

