def test_offsetbox_contains():
    """Test OffsetBox.contains() execution paths."""

    # Create a mock mouse event
    fig, ax = plt.subplots()
    mouse_event = MouseEvent("button_press_event", fig.canvas, 0, 0, MouseButton.LEFT)

    # Path 1: _default_contains returns non-None result
    class MockOffsetBoxWithDefault(OffsetBox):
        def _default_contains(self, mouseevent):
            return True, {"test": "data"}

        def _get_bbox_and_child_offsets(self, renderer):
            return Bbox.from_bounds(0, 0, 10, 10), []

    box1 = MockOffsetBoxWithDefault()
    result = box1.contains(mouse_event)
    assert result == (True, {"test": "data"})

    # Path 2: First child contains the event
    class MockChild1:
        def contains(self, mouseevent):
            return True, {"child": "first"}

    class MockOffsetBoxPath2(OffsetBox):
        def __init__(self):
            super().__init__()
            self._children = [MockChild1()]

        def _default_contains(self, mouseevent):
            return None, {}

        def _get_bbox_and_child_offsets(self, renderer):
            return Bbox.from_bounds(0, 0, 10, 10), [(0, 0)]

    box2 = MockOffsetBoxPath2()
    result = box2.contains(mouse_event)
    assert result == (True, {"child": "first"})

    # Path 3: First child doesn't contain, second child contains
    class MockChild2:
        def contains(self, mouseevent):
