def test_pytest_runtest_makereport_unexpected_success_with_reason(testdir):
    """Test pytest_runtest_makereport handling of unexpected success with reason."""
    testdir.makepyfile(
        """
        import pytest

        class MyItem(pytest.Item):
            nodeid = 'foo'
            def setup(self):
                self._store = {}
            def runtest(self):
                pass

        def pytest_collect_file(path, parent):
            return MyItem("foo", parent)
    """
    )
    # Manually set up the item to trigger the unexpected success path
    from _pytest.skipping import unexpectedsuccess_key
    from _pytest.runner import CallInfo
    from _pytest.reports import TestReport
    from _pytest.skipping import pytest_runtest_makereport
    import pytest as pytest_module

    # Create a mock item with the required attributes
    class MockItem:
        def __init__(self):
            self._store = {unexpectedsuccess_key: "Custom reason"}
            self.config = MockConfig()

        def reportinfo(self):
            return ("test_file.py", 1, "test_nodeid")

    class MockConfig:
        def __init__(self):
            self.option = MockOption()

    class MockOption:
        def __init__(self):
            self.runxfail = False

    class MockCallInfo:
        def __init__(self):
            self.excinfo = None
            self.when = "call"

    # Create the hook caller and call the hook
    item = MockItem()
    call = MockCallInfo()

    # Create a generator to simulate the hook wrapper
    def make_mock_outcome():
        class MockOutcome:
            def get_result(self):
                rep = TestReport("test", ("location", 1, "test"), {}, "skipped", "longrepr", "when")
                # Set longrepr as tuple to trigger the path modification
                rep.longrepr = ("file", 2, "reason")
                return rep
        return MockOutcome()

    # Call the hook function directly
    gen = pytest_runtest_makereport(item, call)
    # Prime the generator
    next(gen)
    # Send the outcome
    try:
        gen.send(make_mock_outcome())
    except StopIteration as e:
        rep = e.value

    # Verify the report was modified correctly
    assert rep.outcome == "failed"
    assert rep.longrepr == "Unexpected success: Custom reason"


