            "__getattr__": lambda self, name: lambda other: False  # always not compatible
        })()
    }

    # Test the function
    result = _diff_mapping_repr(
        mapping_a, 
        mapping_b, 
        compat="identical", 
        title="Variables", 
        summarizer=dummy_summarizer
    )

