def test_item_location(testdir):
    """Test that Item.location handles both py.path.local and str paths."""
    # Create a simple test file
    test_file = testdir.makepyfile(
        """
        def test_example():
            pass
        """
    )

    # Get the item
    items = testdir.getitems(test_file)
    item = items[0]

    # Mock session to control _node_location_to_relpath behavior
    class MockSession:
        def _node_location_to_relpath(self, fspath):
            return fspath.basename

    item.session = MockSession()

    # Test Path 1: reportinfo returns py.path.local
    class MockItemWithPathLocal(nodes.Item):
        def reportinfo(self):
            return (py.path.local("/fake/path/test.py"), 10, "test_example")

    mock_item1 = MockItemWithPathLocal.from_parent(item, name="mock1")
    mock_item1.session = MockSession()

    location = mock_item1.location
    assert location == ("test.py", 10, "test_example")

    # Test Path 2: reportinfo returns str
    class MockItemWithPathStr(nodes.Item):
        def reportinfo(self):
            return ("/fake/path/test.py", 10, "test_example")

    mock_item2 = MockItemWithPathStr.from_parent(item, name="mock2")
    mock_item2.session = MockSession()

    location = mock_item2.location
    assert location == ("test.py", 10, "test_example")

    # Test that the third element is indeed a string (assertion check)
    class MockItemWithNonStrThird(nodes.Item):
        def reportinfo(self):
            return (py.path.local("/fake/path/test.py"), 10, 123)  # Non-string

    mock_item3 = MockItemWithNonStrThird.from_parent(item, name="mock3")
    mock_item3.session = MockSession()

    with pytest.raises(AssertionError):
        _ = mock_item3.location
